#define _XOPEN_SOURCE 700

#include <dirent.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "field.h"
#include "format.h"
#include "util.h"

static int is_continuation(char c)
{
	return ((unsigned char)c & 0xc0) == 0x80;
}

void field_set(struct field *f, const char *text)
{
	size_t n = strlen(text);

	if (n >= sizeof f->text)
		n = sizeof f->text - 1;
	while (n > 0 && is_continuation(text[n]))
		n--;
	memcpy(f->text, text, n);
	f->text[n] = '\0';
	f->len = f->pos = n;
}

static size_t prev_char(const struct field *f, size_t pos)
{
	while (pos > 0 && is_continuation(f->text[--pos]))
		;
	return pos;
}

static size_t next_char(const struct field *f, size_t pos)
{
	if (pos < f->len)
		pos++;
	while (pos < f->len && is_continuation(f->text[pos]))
		pos++;
	return pos;
}

/* Takes out the bytes from start to end. */
static void cut(struct field *f, size_t start, size_t end)
{
	memmove(f->text + start, f->text + end, f->len - end + 1);
	f->len -= end - start;
	f->pos = start;
}

static void insert(struct field *f, const char *s)
{
	size_t n = strlen(s);

	if (f->len + n >= sizeof f->text)
		return;
	memmove(f->text + f->pos + n, f->text + f->pos, f->len - f->pos + 1);
	memcpy(f->text + f->pos, s, n);
	f->len += n;
	f->pos += n;
}

/*
 * Line editing as in a shell: arrows, Home, End, Backspace, Delete, and
 * Ctrl-A, E, B, F, U, K, W. Ctrl-W takes the last path component, so a
 * path loses one directory at a time. Returns 0 for keys it does not use.
 */
int field_key(struct field *f, const struct key *k)
{
	size_t p;
	int c = k->code == KEY_CTRL ? k->text[0] : 0;

	if (k->code == KEY_CHAR) {
		insert(f, k->text);
	} else if (k->code == KEY_BACKSPACE) {
		cut(f, prev_char(f, f->pos), f->pos);
	} else if (k->code == KEY_DELETE || c == 'd') {
		cut(f, f->pos, next_char(f, f->pos));
	} else if (k->code == KEY_LEFT || c == 'b') {
		f->pos = prev_char(f, f->pos);
	} else if (k->code == KEY_RIGHT || c == 'f') {
		f->pos = next_char(f, f->pos);
	} else if (k->code == KEY_HOME || c == 'a') {
		f->pos = 0;
	} else if (k->code == KEY_END || c == 'e') {
		f->pos = f->len;
	} else if (c == 'u') {
		cut(f, 0, f->pos);
	} else if (c == 'k') {
		cut(f, f->pos, f->len);
	} else if (c == 'w') {
		p = f->pos;
		while (p > 0 && f->text[p - 1] == '/')
			p--;
		while (p > 0 && f->text[p - 1] != '/')
			p--;
		cut(f, p, f->pos);
	} else {
		return 0;
	}
	return 1;
}

/* Columns of the text before the cursor. */
size_t field_cursor_width(const struct field *f)
{
	char *head;
	size_t w;

	head = xmalloc(f->pos + 1);
	memcpy(head, f->text, f->pos);
	head[f->pos] = '\0';
	w = text_width(head);
	free(head);
	return w;
}

/* The typed text as a path: "~" and "~/..." are the home directory. */
char *field_path(const char *text, const char *home)
{
	if (home != NULL && text[0] == '~' && text[1] == '\0')
		return xstrdup(home);
	if (home != NULL && text[0] == '~' && text[1] == '/')
		return xjoin(home, text + 2);
	return xstrdup(text);
}

static int compare_strings(const void *a, const void *b)
{
	return strcmp(*(char *const *)a, *(char *const *)b);
}

/*
 * The directories the last component of text may become, each written as
 * text plus the rest of the name and "/", sorted. Hidden ones only when
 * the component starts with a dot.
 */
char **field_complete(const char *text, const char *home, size_t *count)
{
	const char *slash, *prefix;
	char **list = NULL, *head, *dir, *path, *joined;
	size_t head_len, prefix_len, cap = 0;
	struct dirent *de;
	struct stat st;
	DIR *d;

	*count = 0;
	slash = strrchr(text, '/');
	head_len = slash != NULL ? (size_t)(slash - text) + 1 : 0;
	prefix = text + head_len;
	prefix_len = strlen(prefix);
	head = xmalloc(head_len + 1);
	memcpy(head, text, head_len);
	head[head_len] = '\0';
	if (head_len == 0 && strcmp(text, "~") == 0) {
		list = xmalloc(sizeof *list);
		list[0] = xstrdup("~/");
		*count = 1;
		free(head);
		return list;
	}
	dir = head_len > 0 ? field_path(head, home) : xstrdup(".");
	d = opendir(dir);
	while (d != NULL && (de = readdir(d)) != NULL) {
		if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0 ||
		    strncmp(de->d_name, prefix, prefix_len) != 0 ||
		    (de->d_name[0] == '.' && prefix[0] != '.'))
			continue;
		path = xjoin(dir, de->d_name);
		if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) {
			if (*count + 1 >= cap) {
				cap = cap ? cap * 2 : 16;
				list = xrealloc(list, cap * sizeof *list);
			}
			joined = xmalloc(head_len + strlen(de->d_name) + 2);
			strcpy(joined, head);
			strcat(joined, de->d_name);
			strcat(joined, "/");
			list[(*count)++] = joined;
		}
		free(path);
	}
	if (d != NULL)
		closedir(d);
	if (*count > 1)
		qsort(list, *count, sizeof *list, compare_strings);
	free(dir);
	free(head);
	return list;
}

/* The longest common start of the list, ending on a character boundary. */
char *field_common(char *const *list, size_t count)
{
	char *out;
	size_t n, i, k;

	if (count == 0)
		return xstrdup("");
	n = strlen(list[0]);
	for (i = 1; i < count; i++) {
		for (k = 0; k < n && list[i][k] == list[0][k]; k++)
			;
		n = k;
	}
	while (n > 0 && is_continuation(list[0][n]))
		n--;
	out = xmalloc(n + 1);
	memcpy(out, list[0], n);
	out[n] = '\0';
	return out;
}

void field_list_free(char **list, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		free(list[i]);
	free(list);
}
